import { ref } from 'vue'
import { defineStore } from 'pinia'

export type DegradationTier = 'normal' | 'partial' | 'maintenance'

export const useUiStore = defineStore('ui', () => {
  const degradationTier = ref<DegradationTier>('normal')
  const isBannerDismissed = ref(sessionStorage.getItem('degradation-banner-dismissed') === 'true')

  function setDegradationTier(tier: DegradationTier) {
    // Once maintenance is set, it cannot be downgraded by partial signals
    if (tier === 'maintenance' || degradationTier.value !== 'maintenance') {
      degradationTier.value = tier
    }
  }

  function dismissBanner() {
    isBannerDismissed.value = true
    sessionStorage.setItem('degradation-banner-dismissed', 'true')
  }

  function resetDegradation() {
    degradationTier.value = 'normal'
    isBannerDismissed.value = false
    sessionStorage.removeItem('degradation-banner-dismissed')
  }

  return {
    degradationTier,
    isBannerDismissed,
    setDegradationTier,
    dismissBanner,
    resetDegradation,
  }
})

import { ref, computed } from 'vue'
import { defineStore } from 'pinia'
import type { AuthUser } from '@/types/auth'
import type { User } from 'oidc-client-ts'
import { useCartStore } from '@/stores/useCartStore'
import {
  login as authLogin,
  loginCallback,
  register as authRegister,
  logout as authLogout,
  renewToken,
  getUser,
  getAccessToken,
  saveRedirectPath,
  consumeRedirectPath,
  subscribeToAuthEvents,
} from '@/auth/authService'

function mapOidcUser(oidcUser: User): AuthUser {
  const profile = oidcUser.profile
  return {
    id: profile.sub,
    email: (profile.email as string) || '',
    firstName: (profile.given_name as string) || '',
    lastName: (profile.family_name as string) || '',
    roles: (profile.realm_access as { roles?: string[] })?.roles || [],
  }
}

export const useAuthStore = defineStore('auth', () => {
  const user = ref<AuthUser | null>(null)
  const accessToken = ref<string | null>(null)
  const isLoading = ref(false)
  const error = ref<string | null>(null)

  const isAuthenticated = computed(() => !!user.value && !!accessToken.value)
  const displayName = computed(() => {
    if (!user.value) return ''
    if (user.value.firstName) return user.value.firstName
    return user.value.email
  })

  let unsubscribeEvents: (() => void) | null = null

  async function initAuth(): Promise<void> {
    isLoading.value = true
    error.value = null
    try {
      const oidcUser = await getUser()
      const token = getAccessToken(oidcUser)
      if (oidcUser && token) {
        user.value = mapOidcUser(oidcUser)
        accessToken.value = token
      } else if (oidcUser && !token) {
        // Token expired, try silent refresh
        const renewed = await renewToken()
        if (renewed && !renewed.expired && renewed.access_token) {
          user.value = mapOidcUser(renewed)
          accessToken.value = renewed.access_token
        } else {
          user.value = null
          accessToken.value = null
        }
      }
    } catch {
      // OIDC unavailable or stored session invalid — fall back to unauthenticated
      user.value = null
      accessToken.value = null
    } finally {
      isLoading.value = false
    }

    // Merge anonymous cart if authenticated and localStorage still has anonymous ID
    if (user.value && accessToken.value && localStorage.getItem('robomart-user-id')) {
      try {
        await useCartStore().mergeAnonymousCart()
      } catch {
        // Non-blocking — merge failure should not break init
      }
    }

    // Subscribe to OIDC events for cross-tab sync and silent renewal updates
    if (!unsubscribeEvents) {
      unsubscribeEvents = subscribeToAuthEvents({
        onUserLoaded(oidcUser) {
          user.value = mapOidcUser(oidcUser)
          accessToken.value = oidcUser.access_token
        },
        onUserUnloaded() {
          user.value = null
          accessToken.value = null
        },
        onSilentRenewError() {
          user.value = null
          accessToken.value = null
        },
      })
    }
  }

  async function login(idpHint?: string, loginHint?: string, redirectTo?: string): Promise<void> {
    error.value = null
    const params: Record<string, string> = {}
    if (idpHint) {
      params.kc_idp_hint = idpHint
    }
    if (loginHint) {
      params.login_hint = loginHint
    }
    const path =
      redirectTo ?? window.location.pathname + window.location.search + window.location.hash
    saveRedirectPath(path)
    await authLogin(Object.keys(params).length > 0 ? params : undefined)
  }

  async function register(): Promise<void> {
    error.value = null
    saveRedirectPath(window.location.pathname + window.location.search + window.location.hash)
    await authRegister()
  }

  async function handleCallback(): Promise<string> {
    isLoading.value = true
    error.value = null
    try {
      const oidcUser = await loginCallback()
      user.value = mapOidcUser(oidcUser)
      accessToken.value = oidcUser.access_token

      // Merge anonymous cart after login (non-blocking)
      try {
        await useCartStore().mergeAnonymousCart()
      } catch {
        // Merge failure should not block login flow
      }

      return consumeRedirectPath()
    } catch (err) {
      error.value = err instanceof Error ? err.message : 'Authentication failed'
      throw err
    } finally {
      isLoading.value = false
    }
  }

  async function refreshToken(): Promise<boolean> {
    try {
      const renewed = await renewToken()
      if (renewed) {
        user.value = mapOidcUser(renewed)
        accessToken.value = renewed.access_token
        return true
      }
      return false
    } catch {
      user.value = null
      accessToken.value = null
      return false
    }
  }

  async function logout(): Promise<void> {
    try {
      await authLogout()
    } catch {
      // Keycloak might be unreachable — clear local state anyway
    } finally {
      user.value = null
      accessToken.value = null
      error.value = null
    }
  }

  function $reset() {
    user.value = null
    accessToken.value = null
    isLoading.value = false
    error.value = null
  }

  return {
    user,
    accessToken,
    isLoading,
    error,
    isAuthenticated,
    displayName,
    initAuth,
    login,
    register,
    handleCallback,
    refreshToken,
    logout,
    $reset,
  }
})

import { ref, computed } from 'vue'
import { defineStore } from 'pinia'
import { getCart, addToCart, updateQuantity, removeItem, mergeCart } from '@/api/cartApi'
import { clearAnonymousIdCache } from '@/api/client'
import type { CartItem, AddToCartRequest } from '@/types/cart'

export const useCartStore = defineStore('cart', () => {
  const items = ref<CartItem[]>([])
  const isLoading = ref(false)
  const error = ref<string | null>(null)

  const totalItems = computed(() => items.value.reduce((sum, item) => sum + item.quantity, 0))
  const totalPrice = computed(() => items.value.reduce((sum, item) => sum + item.subtotal, 0))

  async function fetchCart() {
    isLoading.value = true
    error.value = null
    try {
      const response = await getCart()
      items.value = response.data.items
    } catch (err) {
      error.value = err instanceof Error ? err.message : 'Failed to load cart'
    } finally {
      isLoading.value = false
    }
  }

  async function addItem(request: AddToCartRequest) {
    const previousItems = items.value.map((item) => ({ ...item }))
    const existing = items.value.find((i) => i.productId === request.productId)
    if (existing) {
      existing.quantity += request.quantity
      existing.subtotal = existing.price * existing.quantity
    } else {
      items.value.push({
        productId: request.productId,
        productName: request.productName,
        price: request.price,
        quantity: request.quantity,
        subtotal: request.price * request.quantity,
      })
    }
    try {
      const response = await addToCart(request)
      items.value = response.data.items
    } catch (err) {
      items.value = previousItems
      error.value = err instanceof Error ? err.message : 'Failed to add item'
      throw err
    }
  }

  async function updateItemQuantity(productId: number, quantity: number) {
    const item = items.value.find((i) => i.productId === productId)
    if (!item || item.quantity === quantity) return
    const previousItems = items.value.map((i) => ({ ...i }))
    item.quantity = quantity
    item.subtotal = item.price * quantity
    try {
      const response = await updateQuantity(productId, { quantity })
      items.value = response.data.items
    } catch (err) {
      items.value = previousItems
      error.value = err instanceof Error ? err.message : 'Failed to update quantity'
      throw err
    }
  }

  async function removeCartItem(productId: number) {
    const previousItems = [...items.value]
    items.value = items.value.filter((i) => i.productId !== productId)
    try {
      await removeItem(productId)
    } catch (err) {
      items.value = previousItems
      error.value = err instanceof Error ? err.message : 'Failed to remove item'
      throw err
    }
  }

  async function mergeAnonymousCart(): Promise<void> {
    const ANONYMOUS_KEY = 'robomart-user-id'
    const anonymousId = localStorage.getItem(ANONYMOUS_KEY)
    if (!anonymousId) return

    try {
      const response = await mergeCart(anonymousId)
      items.value = response.data.items
      localStorage.removeItem(ANONYMOUS_KEY)
      clearAnonymousIdCache()
    } catch (err) {
      console.error('Cart merge failed:', err)
    }
  }

  function $reset() {
    items.value = []
    isLoading.value = false
    error.value = null
  }

  return {
    items,
    isLoading,
    error,
    totalItems,
    totalPrice,
    fetchCart,
    addItem,
    updateItemQuantity,
    removeCartItem,
    mergeAnonymousCart,
    $reset,
  }
})

import { ref } from 'vue'
import { defineStore } from 'pinia'
import {
  getOrders as fetchOrdersApi,
  getOrder as fetchOrderApi,
  cancelOrder as cancelOrderApi,
} from '@/api/orderApi'
import type { OrderSummary, OrderDetail } from '@/types/order'
import type { PaginationMeta } from '@/types/product'

export const useOrderStore = defineStore('order', () => {
  const orders = ref<OrderSummary[]>([])
  const currentOrder = ref<OrderDetail | null>(null)
  const pagination = ref<PaginationMeta | null>(null)
  const isLoading = ref(false)
  const error = ref<string | null>(null)

  async function fetchOrders(page = 0, size = 10) {
    isLoading.value = true
    error.value = null
    try {
      const response = await fetchOrdersApi({ page, size })
      orders.value = response.data
      pagination.value = response.pagination
    } catch (err) {
      error.value = err instanceof Error ? err.message : 'Failed to load orders'
    } finally {
      isLoading.value = false
    }
  }

  async function fetchOrder(orderId: number) {
    isLoading.value = true
    error.value = null
    currentOrder.value = null
    try {
      const response = await fetchOrderApi(orderId)
      currentOrder.value = response.data
    } catch (err) {
      error.value = err instanceof Error ? err.message : 'Failed to load order'
    } finally {
      isLoading.value = false
    }
  }

  async function cancelOrder(orderId: number, reason?: string) {
    isLoading.value = true
    error.value = null
    try {
      await cancelOrderApi(orderId, reason)
    } catch (err) {
      error.value = err instanceof Error ? err.message : 'Failed to cancel order'
      isLoading.value = false
      throw err
    }
    // Cancel succeeded — refresh silently; refetch errors don't indicate cancel failure
    try {
      const response = await fetchOrderApi(orderId)
      currentOrder.value = response.data
    } finally {
      isLoading.value = false
    }
  }

  function $reset() {
    orders.value = []
    currentOrder.value = null
    pagination.value = null
    isLoading.value = false
    error.value = null
  }

  return {
    orders,
    currentOrder,
    pagination,
    isLoading,
    error,
    fetchOrders,
    fetchOrder,
    cancelOrder,
    $reset,
  }
})

import { ref } from 'vue'
import { defineStore } from 'pinia'
import { useRouter } from 'vue-router'
import type { AxiosError } from 'axios'
import { placeOrder as placeOrderApi } from '@/api/orderApi'
import { useCartStore } from '@/stores/useCartStore'
import type { ShippingFormData, PaymentFormData, CheckoutError } from '@/types/checkout'
import { formatShippingAddress } from '@/types/checkout'

const SAGA_MESSAGES = ['Creating your order...', 'Reserving items...', 'Processing payment...']

interface ApiErrorBody {
  error?: {
    code?: string
    message?: string
  }
}

export const useCheckoutStore = defineStore('checkout', () => {
  const router = useRouter()

  const currentStep = ref<1 | 2 | 3 | 4>(1)
  const shippingData = ref<ShippingFormData | null>(null)
  const paymentData = ref<PaymentFormData | null>(null)
  const isPlacingOrder = ref(false)
  const error = ref<CheckoutError | null>(null)
  const sagaMessage = ref(SAGA_MESSAGES[0])

  function nextStep() {
    if (currentStep.value < 4) {
      currentStep.value = (currentStep.value + 1) as 1 | 2 | 3 | 4
    }
  }

  function prevStep() {
    if (currentStep.value > 1) {
      currentStep.value = (currentStep.value - 1) as 1 | 2 | 3 | 4
    }
  }

  function setShippingData(data: ShippingFormData) {
    shippingData.value = data
  }

  function setPaymentData(data: PaymentFormData) {
    paymentData.value = data
  }

  async function placeOrder() {
    const cartStore = useCartStore()
    if (!shippingData.value || !paymentData.value) return
    if (isPlacingOrder.value) return

    error.value = null
    isPlacingOrder.value = true
    sagaMessage.value = SAGA_MESSAGES[0]

    let msgIndex = 0
    const intervalId = setInterval(() => {
      msgIndex = (msgIndex + 1) % SAGA_MESSAGES.length
      sagaMessage.value = SAGA_MESSAGES[msgIndex]
    }, 1500)

    try {
      const request = {
        items: cartStore.items.map((item) => ({
          productId: String(item.productId),
          productName: item.productName,
          quantity: item.quantity,
          unitPrice: item.price,
        })),
        shippingAddress: formatShippingAddress(shippingData.value),
      }

      const result = await placeOrderApi(request)
      await router.push(`/order-confirmation/${result.data.id}`)
      cartStore.$reset()
    } catch (err: unknown) {
      const axiosErr = err as AxiosError<ApiErrorBody>
      const errorCode = axiosErr.response?.data?.error?.code
      const errorMessage = axiosErr.response?.data?.error?.message ?? 'Order processing failed'

      if (errorCode === 'ORDER_INVENTORY_FAILED') {
        error.value = {
          type: 'INVENTORY_FAILED',
          message: errorMessage,
        }
      } else if (errorCode === 'ORDER_PAYMENT_FAILED') {
        error.value = {
          type: 'PAYMENT_FAILED',
          message:
            "Payment couldn't be processed. Your order is saved — try again or use a different method.",
        }
        currentStep.value = 3
      } else {
        error.value = {
          type: 'UNKNOWN',
          message: 'Something went wrong. Please try again.',
        }
      }
    } finally {
      clearInterval(intervalId)
      isPlacingOrder.value = false
    }
  }

  function $reset() {
    currentStep.value = 1
    shippingData.value = null
    paymentData.value = null
    isPlacingOrder.value = false
    error.value = null
    sagaMessage.value = SAGA_MESSAGES[0]
  }

  return {
    currentStep,
    shippingData,
    paymentData,
    isPlacingOrder,
    error,
    sagaMessage,
    nextStep,
    prevStep,
    setShippingData,
    setPaymentData,
    placeOrder,
    $reset,
  }
})

